def count_Primes_nums(n):
    """
    Counts the number of prime numbers less than a given non-negative number n.

    Args:
    n (int): A non-negative integer

    Returns:
    int: The number of prime numbers less than n
    """
    if n <= 2:
        return 0

    # Initialize a list to track prime status of numbers
    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False  # 0 and 1 are not prime numbers

    # Use the Sieve of Eratosthenes algorithm to find all primes less than n
    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            for j in range(i*i, n, i):
                is_prime[j] = False

    # Count and return the number of prime numbers
    return sum(is_prime)

def max_sum(arr):
    """
    Finds the maximum sum of a bitonic subsequence in the given array.
    A bitonic subsequence is first increasing and then decreasing.

    :param arr: List of integers
    :return: Maximum sum of bitonic subsequence
    """
    n = len(arr)
    if n == 0:
        return 0

    # Initialize arrays to store the maximum sum of increasing and decreasing subsequences
    inc = arr.copy()
    dec = arr.copy()

    # Calculate maximum sum of increasing subsequences
    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j] and inc[i] < inc[j] + arr[i]:
                inc[i] = inc[j] + arr[i]

    # Calculate maximum sum of decreasing subsequences
    for i in range(n-2, -1, -1):
        for j in range(i+1, n):
            if arr[i] > arr[j] and dec[i] < dec[j] + arr[i]:
                dec[i] = dec[j] + arr[i]

    # Find the maximum sum of bitonic subsequence
    max_sum = 0
    for i in range(n):
        max_sum = max(max_sum, inc[i] + dec[i] - arr[i])

    return max_sum

def max_product(arr):
    """
    Find the maximum product of an increasing subsequence in the given array.

    :param arr: List of integers
    :return: Maximum product of an increasing subsequence
    """
    n = len(arr)
    if n == 0:
        return 0
    if n == 1:
        return arr[0]

    # Initialize the list to store the maximum product subsequence ending at each index
    max_product_subseq = [1] * n

    # Compute the maximum product subsequence for each element
    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j] and max_product_subseq[i] < max_product_subseq[j] * arr[i]:
                max_product_subseq[i] = max_product_subseq[j] * arr[i]

    # Return the maximum value from the max_product_subseq list
    return max(max_product_subseq)

def last_Digit_Factorial(n):
    # Initialize result
    result = 1

    # Edge case: factorial of 0 or 1 is 1
    if n == 0 or n == 1:
        return 1

    # Calculate factorial and get the last digit
    for i in range(2, n + 1):
        result = (result * i) % 10

    return result

def sum_series(n):
    """
    Calculate the sum of the series n + (n-2) + (n-4) + ... until n-x <= 0.

    Parameters:
    n (int): The starting number of the series.

    Returns:
    int: The sum of the series.
    """
    if n < 0:
        return 0
    elif n % 2 != 0:
        n -= 1  # Adjust n to be even if it's odd
    return n + sum_series(n - 2)

def is_not_prime(n):
    """
    Determine if a number is not prime.

    Args:
    n (int): The number to check.

    Returns:
    bool: True if the number is not prime, False otherwise.
    """
    if n <= 1:
        return True  # 0 and 1 are not prime numbers
    if n <= 3:
        return False  # 2 and 3 are prime numbers
    if n % 2 == 0 or n % 3 == 0:
        return True  # multiples of 2 and 3 are not prime
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return True  # found a divisor, n is not prime
        i += 6
    return False  # no divisors found, n is prime
